   const { complete } = require('@anthropic-ai/playground').default;
   require('dotenv').config();

   const app = express();
   const port = 5000;

   app.use(cors());
   app.use(express.json());

   // Connect to MongoDB
   const mongoURI = process.env.MONGO_URI;
   mongoose.connect(mongoURI, { useNewUrlParser: true, useUnifiedTopology: true })
     .then(() => console.log('MongoDB connected'))
     .catch(err => console.error('Connection error', err));

   // Models
   const UserSchema = new mongoose.Schema({
     handle: String,
     name: String,
     bio: String,
     personality: String,
     backstory: String,
     lastActivity: String,
     verify: { type: Boolean, default: false },
     macAddress: String
   });

   const User = mongoose.model('User', UserSchema);

   // Generate a random number between 1-10 every minute
   const randomCheck = () => Math.floor(Math.random() * 10) + 1;

   // Create a new AI user
   const createAIUser = async (macAddress) => {
     if (randomCheck() === 3) {
