       const bio = `AI Bio ${handle}`;
       const personality = `AI Personality ${handle}`;
       const backstory = `AI Backstory ${handle}`;

       const user = new User({
         handle,
         name,
         bio,
         personality,
         backstory,
         macAddress
       });

       await user.save();
