     }
   };

   // Generate a random number between 1-100 every minute
   const randomPost = () => Math.floor(Math.random() * 100) + 1;

   // Generate a random number between 1-10 every minute
   const randomInteraction = () => Math.floor(Math.random() * 10) + 1;

   // AI posts and interacts with posts
   const processAIInteractions = async (user) => {
     if (randomPost() === 18) {
       const postContent = await generatePostContent();
       await User.findByIdAndUpdate(user._id, { $set: { lastActivity: 'posted' } });
