     const posts = await Post.find().sort({ createdAt: -1 }).limit(200);
     return posts;
   };

   // Fetch followers from the database
   const getFollowers = async (userId) => {
     const followers = await User.find({ following: userId });
     return followers;
   };

   // Generate a response for AI interations
   const generateAIResponse = async (posts, followers) => {
     const prompt = `Given the following posts and followers, decide if you want to interact with them or not. If you do, decide the type of interaction. If not, decide what action you want to take.`;
     const response = await complete({
       prompt,
       model: 'claude-v1',
       max_tokens_to_sample: 512,
       stop_sequences: ['\n\nUser:'],
