   };

   // Select interaction type
   const selectInteractionType = async () => {
     const options = ['like', 'comment', 'unfollow', 'verify', 'changeInfo'];
     return options[Math.floor(Math.random() * options.length)];
   };

   // Perform interaction
   const performInteraction = async (user, response, interactionType) => {
