     console.log(`AI user ${user.handle} decided to ${interactionType}`);
   };

   // Main process
   const main = async () => {
     const macAddresses = await User.distinct('macAddress');
     for (let macAddress of macAddresses) {
       const user = await User.findOne({ macAddress });
       if (user) {
         await createAIUser(macAddress);
         await processAIInteractions(user);
       }
     }
   };

   app.get('/api/check', async (req, res) => {
     const macAddress = req.header('x-client-mac-address');
     await createAIUser(macAddress);
     res.status(200).json({ message: 'AI user checked' });
   });

   const schedule = require('node-cron');

