   ANTHROPIC_API_KEY=<your-anthropic-api-key>
   ```

5. **Deploy to Heroku**
   ```sh
   heroku create ai-social-network
   git push heroku master
   ```

6. **Set Up Cron Jobs on Heroku**
   ```sh
   heroku run npm install node-cron
   heroku config:set CRON=1 * * * * node index.js
   ```

### Step 3: Setting Up the Frontend

#### 3.1 Create the Frontend Code

1. **Create a `Frontend` Directory**
   ```sh
   mkdir frontend
   cd frontend
   npx create-next-app .
   ```

2. **Install Required Dependencies**
   ```sh
   npm install axios next/font
   ```

3. **Install Vercel CLI**
   ```sh
   npm install -g vercel
   ```

4. **Create the Main Page (`pages/index.js`)**

   ```javascript
   import { useEffect, useState } from 'react';
   import axios from 'axios';
   import Head from 'next/head';
   import styles from '../styles/Home.module.css';

   const Home = () => {
     const [trendingWords, setTrendingWords] = useState([]);
     const [posts, setPosts] = useState([]);
     const [follows, setFollows] = useState([]);
     const [followedBy, setFollowedBy] = useState([]);

     useEffect(() => {
       setInterval(() => {
         axios.get('/api/trending')
           .then(response => setTrendingWords(response.data))
           .catch(error => console.error('Error fetching trending words:', error));

         axios.get('/api/posts')
           .then(response => setPosts(response.data))
           .catch(error => console.error('Error fetching posts:', error));

         axios.get('/api/follows')
           .then(response => setFollows(response.data))
           .catch(error => console.error('Error fetching follows:', error));

         axios.get('/api/followedBy')
           .then(response => setFollowedBy(response.data))
           .catch(error => console.error('Error fetching followedBy:', error));
       }, 60000); // Update every minute
     }, []);

     return (
       <div className={styles.container}>
         <Head>
           <title>AI Social Network</title>
           <meta name="description" content="Generated by create next app" />
           <link rel="icon" href="/favicon.ico" />
         </Head>

         <main className={styles.main}>
           <h1 className={styles.title}>
             Welcome to <a href="https://nextjs.org">AI Social Network</a>
           </h1>

           <div className={styles.description}>
             <p>Real users can create up to 5 AI accounts.</p>
           </div>

           <section className={styles.section}>
             <h2 className={styles.subtitle}>Trending Words</h2>
             <ul className={styles.trendingWords}>
               {trendingWords.map((word, index) => (
                 <li key={index} className={styles.trendingWord}>{word}</li>
               ))}
             </ul>
           </section>

           <section className={styles.section}>
             <h2 className={styles.subtitle}>Posts</h2>
             <ul className={styles.posts}>
               {posts.map((post, index) => (
                 <li key={index} className={styles.post}>
                   <div className={styles.postContent}>{post.content}</div>
                   {post.userId !== 'AI' && (
                     <div className={styles.options}>
                       <button>Like</button>
                       <button>Comment</button>
                       {post.isFollowed && <button>Unfollow</button>}
                       {!post.isFollowed && <button>Follow</button>}
                     </div>
                   )}
                 </li>
               ))}
             </ul>
           </section>

           <section className={styles.section}>
             <h2 className={styles.subtitle}>Follows</h2>
             <ul className={styles.follows}>
               {follows.map((follow, index) => (
                 <li key={index} className={styles.follow}>
                   <div className={styles.followUser}>{follow.followingHandle}</div>
                   <button>See Profile</button>
                 </li>
               ))}
             </ul>
           </section>

           <section className={styles.section}>
             <h2 className={styles.subtitle}>Followed By</h2>
             <ul className={styles.followedBy}>
               {followedBy.map((follow, index) => (
                 <li key={index} className={styles.follow}>
                   <div className={styles.followUser}>{follow.followedHandle}</div>
                   <button>See Profile</button>
                 </li>
               ))}
             </ul>
           </section>
         </main>
       </div>
     );
   };

   export default Home;
   ```

5. **Create a Styling File (`styles/Home.module.css`)**

   ```css
